import Foundation

enum AlbumArtFlipDirection {
    case next
    case previous

    var rotation: Double { self == .next ? -180 : 180 }
}

/// Metadata can arrive before the cover, and the item ID can arrive after the title.
/// Item IDs can also be regenerated by a seek. Require changed track metadata
/// before treating a different item ID as a new song.
struct AlbumArtworkTrackTracker {
    private(set) var identifier = UUID()
    private var bundleIdentifier: String?
    private var title = ""
    private var artist = ""
    private var album = ""
    private var sourceTrackIdentifier: String?

    mutating func update(bundleIdentifier: String, title: String, sourceTrackIdentifier: String?,
                         artist: String = "", album: String = "") -> UUID {
        let title = title.trimmingCharacters(in: .whitespacesAndNewlines)
        let artist = artist.trimmingCharacters(in: .whitespacesAndNewlines)
        let album = album.trimmingCharacters(in: .whitespacesAndNewlines)
        let sourceID = sourceTrackIdentifier.flatMap { $0.isEmpty ? nil : $0 }
        let changedSource = sourceID != nil && self.sourceTrackIdentifier != nil && sourceID != self.sourceTrackIdentifier
        let changedTitle = !title.isEmpty && !self.title.isEmpty && title != self.title
        let changedArtist = !artist.isEmpty && !self.artist.isEmpty && artist != self.artist
        let changedAlbum = !album.isEmpty && !self.album.isEmpty && album != self.album
        let changedTrack = self.bundleIdentifier != bundleIdentifier
            || changedTitle
            || (changedSource && (changedArtist || changedAlbum))

        if changedTrack {
            identifier = UUID()
            self.title = title
            self.artist = artist
            self.album = album
            self.sourceTrackIdentifier = sourceID
        } else {
            if !title.isEmpty { self.title = title }
            if !artist.isEmpty { self.artist = artist }
            if !album.isEmpty { self.album = album }
            // Do not bind a replacement ID to the old metadata. If its new
            // title arrives in the next diff, it must still identify a new song.
            if self.sourceTrackIdentifier == nil, let sourceID { self.sourceTrackIdentifier = sourceID }
        }
        self.bundleIdentifier = bundleIdentifier
        return identifier
    }
}

/// A refinement replaces the current destination face, including during a flip.
/// While a flip runs, coalesce later tracks to the newest cover and direction.
struct AlbumArtworkTransition<Artwork> {
    struct Update {
        var artwork: Artwork
        var trackIdentifier: UUID
        var direction: AlbumArtFlipDirection
    }

    enum Change {
        case replace(Artwork)
        case flip(Artwork, AlbumArtFlipDirection)
    }

    private(set) var target: Update
    private(set) var isAnimating = false
    private var pending: Update?

    init(_ initial: Update) { target = initial }

    mutating func receive(_ update: Update) -> Change? {
        if update.trackIdentifier == target.trackIdentifier {
            target = update
            pending = nil
            return .replace(update.artwork)
        }
        if isAnimating {
            pending = update
            return nil
        }
        target = update
        isAnimating = true
        return .flip(update.artwork, update.direction)
    }

    mutating func complete() -> Change? {
        isAnimating = false
        guard let latest = pending else { return nil }
        pending = nil
        return receive(latest)
    }

    mutating func reset(_ update: Update) {
        target = update
        pending = nil
        isAnimating = false
    }
}
